const request = $input.first().json;
const expectedSecret = $vars.AGF_APOLLO_WEBHOOK_SECRET;
const receivedSecret = request.headers?.['x-agf-webhook-secret'] || request.headers?.['X-AGF-Webhook-Secret'];
if (!expectedSecret || receivedSecret !== expectedSecret) throw new Error('Webhook Apollo não autorizado.');
const body = request.body ?? request;
const records = Array.isArray(body.records) ? body.records : [body.record ?? body];
if (!records.length) throw new Error('Nenhum lead recebido.');
return records.map((record, index) => {
  const company = record.company ?? {};
  const contact = record.contact ?? {};
  const companyName = company.name ?? record['Company Name'] ?? record.company_name;
  const fullName = contact.full_name ?? record.full_name ?? [record['First Name'], record['Last Name']].filter(Boolean).join(' ');
  const linkedinUrl = contact.linkedin_url ?? record['Person Linkedin Url'] ?? record.linkedin_url;
  const apolloContactId = contact.apollo_contact_id ?? record['Apollo Contact Id'] ?? record.apollo_contact_id;
  const apolloAccountId = company.apollo_account_id ?? record['Apollo Account Id'] ?? record.apollo_account_id;
  const eventId = record.event_id ?? [apolloContactId || linkedinUrl, record.updated_at || body.sync_id || 'snapshot', index].join(':');
  return { json: {
    external_event_id: String(eventId),
    payload: {
      company: {
        name: companyName,
        apollo_account_id: apolloAccountId || null,
        linkedin_url: company.linkedin_url ?? record['Company Linkedin Url'] ?? null,
        website_domain: company.website_domain ?? record.website_domain ?? record.Website ?? null,
        industry: company.industry ?? record.Industry ?? null,
        city: company.city ?? record['Company City'] ?? record.City ?? null,
        state: company.state ?? record['Company State'] ?? record.State ?? null,
        employee_count: company.employee_count ?? record['# Employees'] ?? null,
        company_size: company.company_size ?? null,
        annual_revenue: company.annual_revenue ?? record['Annual Revenue'] ?? null,
        real_economy: company.real_economy ?? false
      },
      contact: {
        full_name: fullName,
        apollo_contact_id: apolloContactId || null,
        linkedin_url: linkedinUrl,
        title: contact.title ?? record.Title ?? null,
        email: contact.email ?? record.Email ?? null,
        country: contact.country ?? record.Country ?? record['Person Country'] ?? 'Brasil'
      },
      raw: record
    }
  }};
});
